# Generated by secure-by-design v0.1.0 for ISO 27001 A.8.15 + DPDP §8 accountability.
# Reads from ../../privacy-security-manifest.yaml.
# Safe to modify. Safe to delete. Re-run /sbd-deploy to regenerate.
# Docs: docs/scaffolds/audit_log.md
#
# Structured, PII-redacting audit logger. ALL security-relevant events go through here.
# Use audit_log.event(...) for normal events. Use audit_log.security(...) for auth/authz.

from __future__ import annotations

import dataclasses
import hashlib
import json
import re
import sys
from collections.abc import Iterable, Mapping
from dataclasses import dataclass
from datetime import date, datetime, timezone
from typing import Any, Literal, Protocol

Severity = Literal['INFO', 'NOTICE', 'WARN', 'ERROR', 'CRITICAL']
Outcome = Literal['success', 'failure', 'denied']


@dataclass(frozen=True)
class AuditEvent:
    timestamp: str                       # ISO 8601
    action: str                          # e.g. 'patient.create', 'dsr.access', 'auth.login.failed'
    actor: str                           # who did it (user/service ID; never raw email/phone)
    severity: Severity
    outcome: Outcome
    target: str | None = None            # what was acted on (entity ID; never raw PII)
    attrs: dict[str, Any] | None = None  # pre-redacted attributes
    request_id: str | None = None


class AuditSink(Protocol):
    async def write(self, event: AuditEvent) -> None: ...


# Default sink — replace at boot with your real sink (structured logger, SIEM, etc.).
class StderrSink:
    async def write(self, event: AuditEvent) -> None:
        fields = {k: v for k, v in dataclasses.asdict(event).items() if v is not None}
        sys.stderr.write(json.dumps({'kind': 'audit', **fields}) + '\n')


_sink: AuditSink = StderrSink()


def set_audit_sink(sink: AuditSink) -> None:
    global _sink
    _sink = sink


# Manifest-driven sensitivity tiers. Wired up at boot from privacy-security-manifest.yaml.
_sensitive_field_names: set[str] = set()


def configure_redaction(fields: Iterable[str]) -> None:
    global _sensitive_field_names
    _sensitive_field_names = {f.lower() for f in fields}


REDACTED = '[REDACTED]'

COMMON_PII_PATTERNS: list[re.Pattern[str]] = [
    re.compile(r'\b[\w.+-]+@[\w-]+(?:\.[\w-]+)+\b', re.ASCII),  # emails
    re.compile(r'\b(?:\+?91[-\s]?)?[6-9]\d{9}\b', re.ASCII),    # Indian phone numbers
    re.compile(r'\b\d{4}\s?\d{4}\s?\d{4}\b', re.ASCII),         # Aadhaar-like
    re.compile(r'\b[A-Z]{5}\d{4}[A-Z]\b', re.ASCII),            # PAN
]


def _pseudonymize(value: str) -> str:
    return 'pii:' + hashlib.sha256(value.encode('utf-8')).hexdigest()[:12]


def to_plain(value: Any) -> Any:
    """Expose a dataclass or Pydantic model as a dict so redaction can see its fields."""
    if isinstance(value, type):
        return value
    if dataclasses.is_dataclass(value):
        return {f.name: getattr(value, f.name) for f in dataclasses.fields(value)}
    model_dump = getattr(value, 'model_dump', None)
    return model_dump() if callable(model_dump) else value


def redact(value: Any) -> Any:
    value = to_plain(value)
    if value is None or isinstance(value, (bool, int, float)):
        return value
    if isinstance(value, str):
        result = value
        for pattern in COMMON_PII_PATTERNS:
            result = pattern.sub(lambda m: _pseudonymize(m.group(0)), result)
        return result
    if isinstance(value, (list, tuple, set, frozenset)):
        return [redact(v) for v in value]
    if isinstance(value, Mapping):
        out: dict[str, Any] = {}
        for k, v in value.items():
            if str(k).lower() in _sensitive_field_names:
                out[str(k)] = _pseudonymize(v) if isinstance(v, str) else REDACTED
            else:
                out[str(k)] = redact(v)
        return out
    if isinstance(value, (datetime, date)):
        return value.isoformat()
    # Anything else has no fields to walk, and its repr could carry personal data.
    return REDACTED


async def _emit(
    action: str,
    *,
    actor: str,
    severity: Severity,
    outcome: Outcome,
    target: str | None,
    attrs: Mapping[str, Any] | None,
    request_id: str | None,
) -> None:
    await _sink.write(AuditEvent(
        timestamp=datetime.now(timezone.utc).isoformat(),
        action=action,
        actor=actor,
        target=target,
        severity=severity,
        outcome=outcome,
        attrs=redact(attrs) if attrs is not None else None,
        request_id=request_id,
    ))


class AuditLog:
    async def event(
        self,
        action: str,
        *,
        actor: str | None = None,
        target: str | None = None,
        severity: Severity | None = None,
        outcome: Outcome | None = None,
        attrs: Mapping[str, Any] | None = None,
        request_id: str | None = None,
    ) -> None:
        """Standard event — data mutation, resource access, etc."""
        await _emit(
            action,
            actor=actor or 'unknown',
            target=target,
            severity=severity or 'INFO',
            outcome=outcome or 'success',
            attrs=attrs,
            request_id=request_id,
        )

    async def security(
        self,
        action: str,
        *,
        actor: str | None = None,
        target: str | None = None,
        severity: Severity | None = None,
        outcome: Outcome | None = None,
        attrs: Mapping[str, Any] | None = None,
        request_id: str | None = None,
    ) -> None:
        """Auth/authz event. Always logged at NOTICE or higher; failures at WARN."""
        await _emit(
            action,
            actor=actor or 'unknown',
            target=target,
            severity=severity or ('WARN' if outcome == 'failure' else 'NOTICE'),
            outcome=outcome or 'success',
            attrs=attrs,
            request_id=request_id,
        )


audit_log = AuditLog()
